package com.sakti.banking.service; import com.sakti.banking.audit.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AuditService { private final AuditEventRepository repo; public AuditService(AuditEventRepository r){repo=r;} public void record(String actor,String action,String target,String outcome){try{repo.save(new AuditEvent(actor,action,target,outcome));}catch(Exception ignored){}} public List<AuditEvent> recent(String actor){try{return repo.findTop50ByActorOrderByCreatedAtDesc(actor);}catch(Exception e){return List.of();}} }
